export function doGet(e: any): GoogleAppsScript.Content.TextOutput {
  const params = (e && e.parameter) ? e.parameter : {};
  const action = params.action || '';

  let response: GasResponse<unknown> = { success: false, error: `Invalid action: ${action}` };

  const act = String(action);
  if (act.startsWith('getCatalog') || act === 'getCategories') {
    response = categoryGet(params);
  } else if (act === 'getTasks') {
    response = taskGet(params);
  } else if (act === 'getMilestones') {
    response = milestoneGet(params);
  } else if (act === 'getMembers') {
    response = memberGet(params);
  } else if (act === 'getOverdue') {
    response = handleGetOverdue(params);
  } else if (act === 'getAllData') {
    response = getAllData();
  }

  // 固定回傳 JSON
  return ContentService.createTextOutput(JSON.stringify(response))
    .setMimeType(ContentService.MimeType.JSON);
}

export function doPost(e: any): GoogleAppsScript.Content.TextOutput {
  let response: GasResponse<unknown> = { success: false, error: 'No data' };
  
  if (e && e.postData && e.postData.contents) {
    try {
      const payload = JSON.parse(e.postData.contents);
      const action = payload.action;

      const act = String(action);
      if (act === 'createCategory' || act === 'updateCategory' || act === 'deleteCategory') {
        response = categoryPost(payload);
      } else if (act === 'createTask' || act === 'updateTask' || act === 'deleteTask' || act === 'patchTaskOwner' || act === 'patchTaskDates' || act === 'patchTaskSegments') {
        response = taskPost(payload);
      } else if (
        act === 'createMilestone' || act === 'updateMilestone' || act === 'deleteMilestone' ||
        act === 'bulkImport' || act === 'shiftTaskMilestones' ||
        act === 'patchMilestoneOwner' || act === 'patchMilestoneStatus' || act === 'patchMilestoneNotify' || act === 'bulkTransferOwner'
      ) {
        response = milestonePost(payload);
      } else {
        response = { success: false, error: `Invalid POST action: ${action}` };
      }
      // 寫入成功後清除 cache
      if (response.success) {
        invalidateAllDataCache();
      }
    } catch (err: any) {
      response = { success: false, error: err.message };
    }

function runIterationWorker_(event) {
  const p=gasPorts_(),owner=String(p.bootstrap||'').trim().toLowerCase();
  if(!owner||String(Session.getEffectiveUser().getEmail()||'').trim().toLowerCase()!==owner)throw Error('FORBIDDEN');
  const schedule=p.iterationSchedulerStatus();
  if(!schedule.enabled||!event?.triggerUid||String(event.triggerUid)!==schedule.triggerUid)throw Error('FORBIDDEN');
  const d=p.read();
  if(!d?.admins?.some(a=>String(a.email||'').trim().toLowerCase()===owner&&a.active===true))throw Error('FORBIDDEN');
  if(!d.settings?.ITERATION?.value.enabled)return{state:'DISABLED'};
  return createApplication(p).runIteration();
}

function api(envelope) {
  try{
    if(gasRuntime_().mode==='GATEWAY'){
      if(envelope?.action==='case.delivery')return gatewayDelivery_(envelope);
      const result=adminRelay_(envelope);
      if(result.ok&&result.data&&Object.hasOwn(result.data,'webAppUrl'))result.data.webAppUrl=gasRuntime_().gatewayUrl||'';
      return result;
    }
    if(gasRuntime_().mode!=='DIRECT')throw Error('FORBIDDEN');
    return apiLocal_(envelope,gasPorts_());
  }catch(e){return gasError_(e);}
}

