google.script.run
  .withSuccessHandler(function(resp) {
    setLoading(false);
    if (resp && resp.success) {
      state.valuationData = resp.data || [];
      state.activeStockIds.clear();
      state.valuationData.forEach(function(s) {
        if (s.risk_level !== 'NOT_APPLICABLE' || s.skip_reason === '') {
          state.activeStockIds.add(String(s.stock_id));
        }
      });
      renderDashboard(resp);
      showToast('資料整理完成', 'success');
      if (onComplete) onComplete();
    } else {
      showToast(resp.message || '讀取失敗', 'error');
    }
  })
  .withFailureHandler(function(err) {
    setLoading(false);
    showToast('後端發生錯誤: ' + (err.message || err), 'error');
  })
  .getValuationResults();
